// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes memory _data) public {
        vm.assume(callee != address(0) && callee != address(c));
        (bool success,) = address(c).call(abi.encodeWithSignature("forward(address,bytes)", callee, _data));
        assertTrue(success == false);
    }
}
